      "tinypool": "2.2.0"
    },
    "ignoredBuiltDependencies": [
      "esbuild"
    ]
  }
}
// Playwright config (ADR-0012). CF-2 resolution: browsers are NEVER downloaded (`playwright install` is not
// run anywhere). @playwright/test is pinned to exactly 1.56.1, whose browser registry expects chromium-1194;
// that revision is pre-installed under PLAYWRIGHT_BROWSERS_PATH (/opt/pw-browsers in the build sandbox, the
// version-matched Playwright image's /ms-playwright in CI). Changing the pin requires a matching browser
// image and an ADR-0012 update.
import { defineConfig, devices } from "@playwright/test";

const baseURL = process.env["E2E_BASE_URL"] ?? "http://localhost:3000";

export default defineConfig({
  // e2e/** belongs to qa-verifier (acceptance suites); apps/web/e2e/** to frontend-ux-engineer (journeys,
  // visual EN/AR screenshots). Disjoint directories, so parallel worktrees never edit the same spec file.
  testDir: ".",
  testMatch: ["e2e/**/*.spec.ts", "apps/web/e2e/**/*.spec.ts"],
  testIgnore: ["**/node_modules/**"],
  outputDir: "test-results",
  fullyParallel: false,
  forbidOnly: true,
  retries: 0,
  reporter: [["list"], ["html", { open: "never", outputFolder: "playwright-report" }]],
  use: {
    baseURL,
    trace: "retain-on-failure",
    screenshot: "only-on-failure",
  },
  projects: [
    { name: "chromium-en", use: { ...devices["Desktop Chrome"], locale: "en-US", timezoneId: "Asia/Riyadh" } },
    { name: "chromium-ar", use: { ...devices["Desktop Chrome"], locale: "ar-SA", timezoneId: "Asia/Riyadh" } },
  ],
});
// Root Vitest config (ADR-0012). Four projects:
//   unit-node              - pure unit tests of API/worker/packages (no network, no database)
//   unit-web               - React component/unit tests in jsdom (apps/web/vitest.config.ts)
//   unit-formula-nocodegen - the formula engine tests again, in a Node process started with
//                            --disallow-code-generation-from-strings (ADR-0024 §6, F-DG3-100)
//   integration            - tests against a real, disposable PostgreSQL database per run (TEST_DATABASE_ADMIN_URL)
// qa-verifier's acceptance suites live under tests/qa/{unit,integration}/ and join the matching project.
import { configDefaults, defineConfig } from "vitest/config";

/** The canary only holds in the no-codegen process, so it runs in that project alone. */
const NOCODEGEN_CANARY = "packages/shared/src/formula/**/*.nocodegen.test.ts";
const NOCODEGEN_PROJECT = "unit-formula-nocodegen";
const NOCODEGEN_FLAG = "--disallow-code-generation-from-strings";
/** Lets tinypool start a fork under the flag (see the file header); it enables no code generation. */
const NOCODEGEN_PRELOAD = new URL("./packages/shared/src/formula/test-support/nocodegen-preload.mjs", import.meta.url)
  .href;

/**
 * The --project names selected on this Vitest command line. Vitest 3.2 takes the forks pool execArgv from the ROOT
 * poolOptions only (a project-level poolOptions.forks.execArgv is ignored), worker threads refuse the flag
 * (ERR_WORKER_INVALID_EXEC_ARGV) and node:vm contexts (vmForks) re-enable string code generation. So the no-codegen
 * project runs as its own Vitest invocation (`pnpm test` runs it after unit-node and unit-web), and only that
 * invocation starts its forks with the flag.
 */
const selectedProjects = process.argv.flatMap((arg, i, all) =>
  arg === "--project" && all[i + 1] !== undefined
    ? [all[i + 1]]
    : arg.startsWith("--project=")
      ? [arg.slice("--project=".length)]
      : [],
);
const nocodegenRun = selectedProjects.includes(NOCODEGEN_PROJECT);
if (nocodegenRun && selectedProjects.length > 1) {
  throw new Error(
    `Run --project ${NOCODEGEN_PROJECT} in its own vitest invocation: its forks start with ${NOCODEGEN_FLAG}, which the other projects must not inherit.`,
  );
}

export default defineConfig({
  test: {
    // Root-level, so Vitest honours it; empty except in the no-codegen invocation (see selectedProjects above).
    poolOptions: { forks: { execArgv: nocodegenRun ? [NOCODEGEN_FLAG, "--import", NOCODEGEN_PRELOAD] : [] } },
    projects: [
      {
        resolve: { conditions: ["@mth/source"] },
        // Node-environment tests transform workspace deps through Vite's SSR pipeline, which uses its own condition
        // list; without this, `@mth/source` is honored only by the non-SSR resolver and tests load stale built dist
        // (T-DG1-BE R-1). Mirror the source condition into SSR resolution and externalization.
        ssr: { resolve: { conditions: ["@mth/source"], externalConditions: ["@mth/source"] } },
        test: {
          name: "unit-node",
          environment: "node",
          include: [
            "apps/api/src/**/*.test.ts",
            "apps/worker/src/**/*.test.ts",
            "packages/*/src/**/*.test.ts",
            "tests/qa/unit/**/*.test.ts",
            // ADR-0052 §6: the offline dependency audit runs in `pnpm test` (T-DG6-DO-A)
            "deploy/scripts/tests/**/*.vitest.mjs",
          ],
          exclude: [...configDefaults.exclude, NOCODEGEN_CANARY],
        },
      },
      {
        // ADR-0024 §6 run-time guard (F-DG3-100): the whole formula test corpus (formula.test.ts, fuzz.test.ts and every
        // other test under packages/shared/src/formula) runs a second time in forked Node processes started with
        // --disallow-code-generation-from-strings. There, eval and every Function, AsyncFunction or GeneratorFunction
        // construction from a string throw EvalError, however the constructor was reached and whatever the key was
        // spelled. Any engine path that generates code from a string, and that a test exercises, fails here. The canary
        // (*.nocodegen.test.ts) proves the flag is active, so the guard cannot silently disappear: run this project in any
        // other way (without --project unit-formula-nocodegen) and the canary fails. Vitest itself is unaffected: it
        // loads modules through node:vm script compilation, which the flag does not restrict.
        resolve: { conditions: ["@mth/source"] },
        ssr: { resolve: { conditions: ["@mth/source"], externalConditions: ["@mth/source"] } },
        test: {
          name: NOCODEGEN_PROJECT,
          environment: "node",
          include: ["packages/shared/src/formula/**/*.test.ts"],
          pool: "forks",
        },
      },
      "apps/web/vitest.config.ts",
      {
        resolve: { conditions: ["@mth/source"] },
        ssr: { resolve: { conditions: ["@mth/source"], externalConditions: ["@mth/source"] } },
        test: {
          name: "integration",
          environment: "node",
          include: [
            "apps/*/test/integration/**/*.test.ts",
            "packages/*/test/integration/**/*.test.ts",
            "tests/qa/integration/**/*.test.ts",
          ],
          // One disposable database per run; created/dropped by the global setup owned by backend-workflow-engineer.
          globalSetup: ["packages/db/test/global-setup.ts"],
          // Integration files MUST run serially: they share the disposable database, and project-level
          // `fileParallelism` is not honored by this vitest (F-DG1-009). `poolOptions.forks.singleFork` IS honored
          // per project and runs every file of this project in a single fork, one after another, so no two integration
          // files run concurrently (no cross-file row pollution, and a forced database drop never races another file).
          pool: "forks",
          poolOptions: { forks: { singleFork: true } },
          fileParallelism: false,
          testTimeout: 30_000,
          // F-DG1-136: hooks get the same budget as tests. A teardown afterAll (DDL + api.close() + dropScratchDatabase(),
          // which itself waits up to 10s for other backends to disconnect) must not hit vitest's default 10_000 ms hookTimeout.
          hookTimeout: 30_000,
        },
      },
    ],
  },
});
# Agent operating protocol (shared by all project agents)

This file is mandatory reading for every project agent in `.claude/agents/`. It condenses section 0 of `docs/source/master-prompt-v2.0.md`. Where they differ, the master prompt wins.

## Two gate systems: never mix them

- **DG0–DG7** are *software delivery gates* for the engineering team. Their records live in `docs/delivery/`.
- **G1–G6** are *business transformation approvals inside the product* (Case for Change … Sustain). They are product features.
- An engineering agent can never grant a real business, Finance or IT production approval. A demo Sponsor approval in seed data approves nothing real.
- Product gate G6 (Sustain) never implies that engineering gate DG7 has passed, and DG7 never implies any G1–G6 business approval.

## Sources of truth

| What | Where |
|---|---|
| Authoritative methodology (playbook v1.0) | `docs/source/playbook.md` (block anchors `B0001`–`B0165`); original `docs/source/Business_Transformation_Playbook.docx` |
| Product and delivery requirements | `docs/source/master-prompt-v2.0.md` (sections §0–§21) |
| Requirement register | `docs/delivery/requirements.csv` |
| Stage state and candidates | `docs/delivery/stages.json`, `docs/delivery/candidates/` |
| Decisions and assumptions | `docs/delivery/decisions.md` |
| Findings | `docs/delivery/findings.json` |
| Reviews / gates | `docs/delivery/reviews/DGx/round-N/`, `docs/delivery/gates/DGx.json` |
| Gate rules (validator) | `tools/gates/` (implementers must not edit it) |

## Assignment contract (what every delegation contains)

Every assignment names: stage ID; task and requirement IDs; exact source/reference files; candidate/base revision; permitted files; constraints; input/output contracts; acceptance checks; dependency status; and the expected handback path. If any of these is missing or contradictory, say so in your handback. Do not guess.

Verify the starting revision (`git rev-parse HEAD`, and `git status`) before you write anything. Do not assume your workspace contains the latest integration candidate.

## Implementation handback contract

Write your handback to the path given in the assignment (default `docs/delivery/handbacks/<stage>/<task-id>-<role>.md`). It must contain:

1. **Changed files**, with a one-line purpose for each.
2. **Behaviour delivered**, per requirement ID.
3. **Checks actually run**: exact command, environment, and the actual result or exit status. Paste the relevant output tail.
4. **Known gaps / not done**, stated plainly. An unfinished task is unfinished even if everything else went well.
5. **Merge instructions** (migrations to run, ordering, conflicts to expect).

Never report a check as passed if you did not run it. If a tool, credential or service is missing, report the check as **BLOCKED** with the exact reason.

## Review record contract (reviewers and auditor)

Reviewers write one JSON record to `docs/delivery/reviews/<DGx>/round-<N>/<role>.json`. Create it and your sidecars **only with the Write/Edit tools**, never through the shell: the validator binds each of them to the content your run's own **successful** Write/Edit calls produce when replayed from your transcript (D-021). A file you also modify through the shell no longer matches, and is rejected. They're write-once, so never edit a file from an earlier round. The record goes that conforms to `tools/gates/schemas/review.schema.json`, plus an optional Markdown narrative next to it. Required fields: `stage_id`, `candidate_id`, `source_commit`, `reviewer_role`, `invocation_reference`, `implementation_author`, `independence_declaration`, `requirements_checked`, `checks_run[]` (each with `procedure`, `command` where applicable, `environment`, `expected`, `actual`, `exit_status`, `result`), `findings[]` (finding IDs), `verdict` (PASS/FAIL/BLOCKED), `evidence_paths[]`, `reviewed_at`.

- Inspect the frozen candidate directly: source, diffs, rendered screens, running behaviour. An implementer's summary is not evidence.
- Form your verdict **before** reading any other reviewer's conclusions for the same round.
- For your `invocation_reference`, copy exactly the value the orchestrator gives you. Never invent run IDs.
- A reviewer must not have authored any implementation in the reviewed scope. If you did, declare it and return BLOCKED.
- Anything you cannot check: record it as BLOCKED with the reason. Never write PASS by default.
- Every evidence entry (in `evidence_paths`, a check's `evidence` or a verification's `evidence`) must be an existing regular file in the repository, optionally followed by `#fragment`. Directories and annotated strings are rejected by the validator.

## Findings contract

Each finding gets a stable ID `F-<DGx>-<NNN>` (the orchestrator allocates numbers; propose them in your record as `F-<DGx>-<role-prefix>-<n>` if you have none yet). Each one records: requirement ID, severity, reproduction, expected vs actual, evidence, and `mandatory_violation` (true if it breaks a mandatory requirement, data integrity, calculation accuracy, access control or deployment portability).

| Severity | Use for |
|---|---|
| Critical | Exploitable severe security flaw, data loss, fundamentally invalid financial results |

