      code: uniq("qa-a17-ok-").toLowerCase(),
      adapterKind: "test_adapter",
      targetTransformationId: k.transformationId,
      adapterSettings: { mode: "healthy", fixture: { rows: fixtureRows, controlColumn: "value" } },
    });
