export function qaBoss(appUrl: string, name: string) {
  const boss = createBoss(appUrl, {
    schedule: false,
    supervise: true,
    superviseIntervalSeconds: 1,
    monitorIntervalSeconds: 1,
    applicationName: name,
  });
  boss.on("error", () => undefined);
  return boss;
}

/** The production worker (every registered domain handler) in this process, with the QA retry policy. */
export async function inProcessWorker(env: ScratchEnv, boss: ReturnType<typeof createBoss>): Promise<RunningWorker> {
  return startWorker({
    db: env.api.db,
    boss,
    timeZone: "Asia/Riyadh",
    pollIntervalMs: 100,
    jobPollingIntervalSeconds: 0.5,
    queuePolicy: QA_QUEUE_POLICY,
    log: quiet,
  });
}

export const CHILD_APP_NAME = "qa-a13-child-worker";

/** The production worker in a separate OS process (a13-child-worker.ts); resolves when it reports READY. */
export async function childWorker(appUrl: string): Promise<{ child: ChildProcess; output: () => string }> {
  const child = spawn(
    process.execPath,
    ["--conditions=@mth/source", fileURLToPath(new URL("./a13-child-worker.ts", import.meta.url))],
    {
      env: { ...process.env, QA_CHILD_DB_URL: appUrl, QA_CHILD_POLICY: JSON.stringify(QA_QUEUE_POLICY) },
      stdio: ["ignore", "pipe", "pipe"],
    },
  );
  let out = "";
  child.stdout!.on("data", (b: Buffer) => (out += b.toString()));
  child.stderr!.on("data", (b: Buffer) => (out += b.toString()));
  await waitFor(
    async () => {
      if (child.exitCode !== null) throw new Error(`child worker exited (${child.exitCode}) before READY: ${out}`);
    );

    const committed = await commit(res.body.importBatchId, batch.body.version);
    expect(committed.status, JSON.stringify(committed.body)).toBe(200);
    expect(committed.body).toMatchObject({ status: "committed", rowsCommitted: 8 });
    expect(await countActuals()).toBe(before + 8);
    expect(decimalCanon((await slot(kpis.direct, periods[0]!))!.value)).toBe("120.5");

    const snapshot = await actualsSnapshot();
    const replay = await post(headers);
    expect(replay.status, JSON.stringify(replay.body)).toBe(200);
    expect(replay.body).toMatchObject({ replay: true, importBatchId: res.body.importBatchId });
    expect(await receipts()).toBe(1);
    expect(await actualsSnapshot()).toEqual(snapshot);
  });
});

// ------------------------------------------------------------------ connectors

/** Executes the connector's due runs the way the API process does, until `runId` is final. */
async function driveRun(connectorId: string, runId: string): Promise<Loose> {
  return waitFor(
    async () => {
      await connectorRunWatchStep(api.db, { onlyConnectors: [connectorId] });
      const d = await call<Loose>(api.app, "GET", `${CONNECTORS}/${connectorId}/runs/${runId}`, { session: admin });
      expect(d.status, JSON.stringify(d.body)).toBe(200);
      return ["succeeded", "failed", "cancelled"].includes(d.body.run.status) ? d.body : null;
    },
    `run ${runId} final`,
    45_000,
  );

