+  it("negative control: the same logs with one leaked canary fail (exit 1) and the scan never prints the value", () => {
+    const bad = mkdtempSync(join(tmpdir(), "qa-a22-scan-bad-"));
+    cpSync(dir, bad, { recursive: true });
+    writeFileSync(
