const EXAMPLE_NORTH_STAR = "Make international roaming effortless, trusted and economically accretive.";
const BLOCK = /^B0(0\d\d|1[0-5]\d|16[0-5])$/;
const TEMPLATES = Array.from({ length: 16 }, (_, i) => `T${String(i + 1).padStart(2, "0")}`);

